DROP DATABASE IF EXISTS mjstudio;
CREATE DATABASE mjstudio CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE mjstudio;

CREATE TABLE user_info (
  id INT NOT NULL AUTO_INCREMENT,
  username VARCHAR(50) NOT NULL,
  password VARCHAR(255) NOT NULL,
  dpprofile LONGBLOB,
  dpcover LONGBLOB,
  email VARCHAR(100),
  PRIMARY KEY (id),
  UNIQUE KEY uniq_username (username)
) ENGINE=InnoDB;

CREATE TABLE status (
  id INT NOT NULL AUTO_INCREMENT,
  postby VARCHAR(50) NOT NULL,
  time DATETIME NOT NULL,
  text TEXT NOT NULL,
  PRIMARY KEY (id),
  KEY idx_status_postby (postby),
  CONSTRAINT fk_status_user FOREIGN KEY (postby) REFERENCES user_info (username) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB;

CREATE TABLE test (
  id INT NOT NULL AUTO_INCREMENT,
  testt VARCHAR(100),
  PRIMARY KEY (id)
) ENGINE=InnoDB;

CREATE TABLE gambo (
  id INT NOT NULL AUTO_INCREMENT,
  image LONGBLOB,
  PRIMARY KEY (id)
) ENGINE=InnoDB;

CREATE TABLE image (
  id INT NOT NULL AUTO_INCREMENT,
  dp LONGBLOB,
  PRIMARY KEY (id)
) ENGINE=InnoDB;

